draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + (20 + 10*Math.sin(t))*Math.cos(i), H/2 + (20 + 10*Math.sin(t))*Math.sin(i), 5, 0, 2*Math.PI);
    ctx.stroke();
  }
  ctx.restore();
}
